failed.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/media/greeting": {\n      "get": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "Say hello in the format you ask for",\n        "description": "Send `Accept` with any of the media types below. The same greeting is rendered as JSON, XML, YAML, plain text, HTML, or Markdown. `Accept: text/html;q=0.9, application/json;q=0.5` picks HTML.",\n        "operationId": "greeting",\n        "parameters": [\n          {\n            "name": "name",\n            "in": "query",\n            "description": "Who to greet.",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "maxLength": 40,\n              "default": "axle"\n            },\n            "example": "Ada"\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "The greeting.",\n            "headers": {\n              "Vary": {\n                "description": "The request headers the response depends on.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "Accept"\n              },\n              "Content-Language": {\n                "description": "The language of the greeting.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "en"\n              }\n            },\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Greeting"\n                }\n              },\n              "application/xml": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Greeting"\n                }\n              },\n              "application/yaml": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Greeting"\n                }\n              },\n              "text/plain": {\n                "schema": {\n                  "type": "string"\n                }\n              },\n              "text/html": {\n                "schema": {\n                  "type": "string"\n                }\n              },\n              "text/markdown": {\n                "schema": {\n                  "type": "string"\n                }\n              }\n            }\n          },\n          "406": {\n            "description": "None of the requested media types can be produced.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "4XX": {\n            "description": "Any other client error.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "5XX": {\n            "description": "Any server error.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "default": {\n            "description": "Anything else.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/media/login": {\n      "post": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "Sign in with a form or JSON",\n        "description": "The same `LoginForm` schema is accepted as `application/x-www-form-urlencoded` or `application/json`. Use `demo` and `demo`.",\n        "operationId": "login",\n        "requestBody": {\n          "required": true,\n          "content": {\n            "application/x-www-form-urlencoded": {\n              "schema": {\n                "\$ref": "#/components/schemas/LoginForm"\n              },\n              "examples": {\n                "demo": {\n                  "summary": "The demo account",\n                  "value": {\n                    "username": "demo",\n                    "password": "demo"\n                  }\n                },\n                "wrong": {\n                  "summary": "Rejected with 401",\n                  "value": {\n                    "username": "demo",\n                    "password": "nope"\n                  }\n                }\n              }\n            },\n            "application/json": {\n              "schema": {\n                "\$ref": "#/components/schemas/LoginForm"\n              },\n              "examples": {\n                "demo": {\n                  "summary": "The demo account",\n                  "value": {\n                    "username": "demo",\n                    "password": "demo"\n                  }\n                },\n                "wrong": {\n                  "summary": "Rejected with 401",\n                  "value": {\n                    "username": "demo",\n                    "password": "nope"\n                  }\n                }\n              }\n            }\n          }\n        },\n        "responses": {\n          "200": {\n            "description": "Signed in.",\n            "headers": {\n              "Set-Cookie": {\n                "description": "Also sets the session cookie `api_session`.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "api_session=demo-key; HttpOnly; SameSite=Strict; Path=/"\n              }\n            },\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Token"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "401": {\n            "description": "Wrong credentials.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "415": {\n            "description": "The request body media type is not supported.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/media/logo": {\n      "get": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "An image as PNG or SVG",\n        "description": "PNG is binary, so its schema is `string` with `format: binary`. SVG is text. Send `If-None-Match` with the `ETag` to get `304`.",\n        "operationId": "logo",\n        "parameters": [\n          {\n            "name": "If-None-Match",\n            "in": "header",\n            "description": "An `ETag` from an earlier response.",\n            "required": false,\n            "schema": {\n              "type": "string"\n            },\n            "example": "\\"logo-v1\\""\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "The image.",\n            "headers": {\n              "ETag": {\n                "schema": {\n                  "type": "string"\n                },\n                "example": "\\"logo-v1\\""\n              },\n              "Cache-Control": {\n                "schema": {\n                  "type": "string"\n                },\n                "example": "public, max-age=86400, immutable"\n              },\n              "Vary": {\n                "description": "The request headers the response depends on.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "Accept"\n              }\n            },\n            "content": {\n              "image/png": {\n                "schema": {\n                  "type": "string",\n                  "format": "binary"\n                }\n              },\n              "image/svg+xml": {\n                "schema": {\n                  "type": "string"\n                }\n              }\n            }\n          },\n          "304": {\n            "description": "The cached copy is still current.",\n            "headers": {\n              "ETag": {\n                "schema": {\n                  "type": "string"\n                },\n                "example": "\\"logo-v1\\""\n              }\n            }\n          },\n          "406": {\n            "description": "None of the requested media types can be produced.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/media/report": {\n      "get": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "A report as JSON, CSV, or TSV",\n        "description": "The JSON form has a schema. The CSV and TSV forms are flat text with a header row, sent as an attachment so browsers download them.",\n        "operationId": "report",\n        "responses": {\n          "200": {\n            "description": "The report.",\n            "headers": {\n              "Content-Disposition": {\n                "description": "Asks the browser to save the file.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "attachment; filename=\\"report.csv\\""\n              },\n              "Vary": {\n                "description": "The request headers the response depends on.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "Accept"\n              }\n            },\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Report"\n                }\n              },\n              "text/csv": {\n                "schema": {\n                  "type": "string"\n                }\n              },\n              "text/tab-separated-values": {\n                "schema": {\n                  "type": "string"\n                }\n              }\n            }\n          },\n          "406": {\n            "description": "None of the requested media types can be produced.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "4XX": {\n            "description": "Any other client error.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "5XX": {\n            "description": "Any server error.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "default": {\n            "description": "Anything else.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/media/stream/events": {\n      "get": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "Server-sent events",\n        "description": "Each event has an `id`, an `event` name, and JSON in `data`. Use `EventSource` in a browser.",\n        "operationId": "streamEvents",\n        "parameters": [\n          {\n            "name": "count",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "integer",\n              "minimum": 1,\n              "maximum": 20,\n              "default": 3\n            }\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "An endless-style event stream; this one ends after `count`.",\n            "headers": {\n              "Cache-Control": {\n                "schema": {\n                  "type": "string"\n                },\n                "example": "no-cache"\n              }\n            },\n            "content": {\n              "text/event-stream": {\n                "schema": {\n                  "type": "string"\n                },\n                "example": "id: 1\\nevent: tick\\ndata: {\\"n\\":1}\\n\\n"\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/media/stream/ndjson": {\n      "get": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "Stream rows as newline-delimited JSON",\n        "description": "Each line is one `ReportRow`. Read the response as it arrives instead of waiting for the end.",\n        "operationId": "streamNdjson",\n        "parameters": [\n          {\n            "name": "count",\n            "in": "query",\n            "description": "How many rows to send.",\n            "required": false,\n            "schema": {\n              "type": "integer",\n              "minimum": 1,\n              "maximum": 1000,\n              "default": 5\n            }\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "One JSON object per line.",\n            "headers": {\n              "Transfer-Encoding": {\n                "description": "The body is streamed in chunks.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "chunked"\n              }\n            },\n            "content": {\n              "application/x-ndjson": {\n                "schema": {\n                  "\$ref": "#/components/schemas/ReportRow"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/media/upload": {\n      "post": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "Upload files with multipart/form-data",\n        "description": "Fields: `title` (text), `tags` (text, repeat it), `cover` (one file), `attachments` (any number of files). The server reads every part and reports what arrived.",\n        "operationId": "upload",\n        "requestBody": {\n          "required": true,\n          "content": {\n            "multipart/form-data": {\n              "schema": {\n                "\$ref": "#/components/schemas/UploadForm"\n              }\n            }\n          }\n        },\n        "responses": {\n          "201": {\n            "description": "Everything that arrived.",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/UploadResult"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "413": {\n            "description": "The upload is larger than 5 MB.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "415": {\n            "description": "The request body media type is not supported.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      },\n      "options": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "What can I send to the upload route?",\n        "operationId": "uploadOptions",\n        "responses": {\n          "204": {\n            "description": "The methods and media types the route accepts.",\n            "headers": {\n              "Allow": {\n                "schema": {\n                  "type": "string"\n                },\n                "example": "POST, OPTIONS"\n              },\n              "Accept-Post": {\n                "schema": {\n                  "type": "string"\n                },\n                "example": "multipart/form-data"\n              }\n            }\n          }\n        }\n      }\n    },\n    "/media/vendor": {\n      "get": {\n        "tags": [\n          "Media"\n        ],\n        "summary": "Content negotiation with a vendor media type",\n        "description": "Send `Accept: application/vnd.axle.v2+json` for the versioned form, or `application/json` for the default.",\n        "operationId": "vendorGreeting",\n        "responses": {\n          "200": {\n            "description": "OK",\n            "headers": {\n              "Vary": {\n                "description": "The request headers the response depends on.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "Accept"\n              }\n            },\n            "content": {\n              "application/vnd.axle.v2+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Greeting"\n                }\n              },\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Greeting"\n                }\n              }\n            }\n          },\n          "406": {\n            "description": "None of the requested media types can be produced.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/parameters/cookies": {\n      "get": {\n        "tags": [\n          "Parameters"\n        ],\n        "summary": "Cookie parameters",\n        "description": "Send `Cookie: theme=dark; visits=3; consent=true; session=abc`. Cookies are strings on the wire; axle documents the type each one parses to.",\n        "operationId": "cookieParameters",\n        "parameters": [\n          {\n            "name": "session",\n            "in": "cookie",\n            "required": true,\n            "schema": {\n              "type": "string",\n              "minLength": 3\n            },\n            "example": "abc"\n          },\n          {\n            "name": "theme",\n            "in": "cookie",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "enum": [\n                "light",\n                "dark"\n              ]\n            }\n          },\n          {\n            "name": "visits",\n            "in": "cookie",\n            "required": false,\n            "schema": {\n              "type": "integer",\n              "minimum": 0\n            }\n          },\n          {\n            "name": "consent",\n            "in": "cookie",\n            "required": false,\n            "schema": {\n              "type": "boolean"\n            }\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/ParsedParameters"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/parameters/formats": {\n      "get": {\n        "tags": [\n          "Parameters"\n        ],\n        "summary": "Formats, patterns, and bounds",\n        "description": "Each parameter has a `format` or `pattern`. Swagger UI shows them as hints; clients can validate before sending.",\n        "operationId": "formats",\n        "parameters": [\n          {\n            "name": "email",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "format": "email"\n            },\n            "example": "a@b.co"\n          },\n          {\n            "name": "id",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "format": "uuid"\n            },\n            "example": "8b8e3c8e-6c6f-4e1b-9d3e-0d7c1d2b9a10"\n          },\n          {\n            "name": "website",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "format": "uri"\n            }\n          },\n          {\n            "name": "day",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "format": "date"\n            },\n            "example": "2026-10-24"\n          },\n          {\n            "name": "ipv4",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "format": "ipv4"\n            },\n            "example": "192.0.2.1"\n          },\n          {\n            "name": "ipv6",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "format": "ipv6"\n            },\n            "example": "2001:db8::1"\n          },\n          {\n            "name": "host",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "format": "hostname"\n            }\n          },\n          {\n            "name": "int32",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "integer",\n              "format": "int32",\n              "minimum": -2147483648\n            }\n          },\n          {\n            "name": "int64",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "integer",\n              "format": "int64"\n            }\n          },\n          {\n            "name": "float",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "number",\n              "format": "float",\n              "minimum": 0,\n              "maximum": 1\n            }\n          },\n          {\n            "name": "zip",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "pattern": "^\\\\d{5}(-\\\\d{4})?\$"\n            },\n            "example": "94105"\n          },\n          {\n            "name": "rating",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "integer",\n              "minimum": 1,\n              "maximum": 5\n            }\n          },\n          {\n            "name": "code",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "minLength": 3,\n              "maxLength": 3\n            }\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/ParsedParameters"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/parameters/label/{ids}": {\n      "get": {\n        "tags": [\n          "Parameters"\n        ],\n        "summary": "Path array, label style",\n        "description": "Values start with a dot: `/parameters/label/.1.2.3`.",\n        "operationId": "labelPath",\n        "parameters": [\n          {\n            "name": "ids",\n            "in": "path",\n            "required": true,\n            "style": "label",\n            "schema": {\n              "type": "array",\n              "items": {\n                "type": "integer"\n              }\n            },\n            "example": [\n              1,\n              2,\n              3\n            ]\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/ParsedParameters"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/parameters/matrix/{ids}": {\n      "get": {\n        "tags": [\n          "Parameters"\n        ],\n        "summary": "Path array, matrix style",\n        "description": "Values carry their name: `/parameters/matrix/;ids=1,2,3`.",\n        "operationId": "matrixPath",\n        "parameters": [\n          {\n            "name": "ids",\n            "in": "path",\n            "required": true,\n            "style": "matrix",\n            "schema": {\n              "type": "array",\n              "items": {\n                "type": "integer"\n              }\n            },\n            "example": [\n              1,\n              2,\n              3\n            ]\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/ParsedParameters"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/parameters/pair/{kind}/{id}": {\n      "get": {\n        "tags": [\n          "Parameters"\n        ],\n        "summary": "Two path parameters, one an enum",\n        "operationId": "pairPath",\n        "parameters": [\n          {\n            "name": "kind",\n            "in": "path",\n            "description": "What the id refers to.",\n            "required": true,\n            "schema": {\n              "type": "string",\n              "enum": [\n                "user",\n                "team"\n              ]\n            }\n          },\n          {\n            "name": "id",\n            "in": "path",\n            "required": true,\n            "schema": {\n              "type": "integer",\n              "minimum": 1\n            },\n            "example": 7\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/ParsedParameters"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "404": {\n            "description": "Unknown kind.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/parameters/search": {\n      "get": {\n        "tags": [\n          "Parameters"\n        ],\n        "summary": "Every way to send arrays and objects in a query string",\n        "description": "| Parameter | Style | Looks like |\\n| --- | --- | --- |\\n| `tags` | `form`, exploded | `tags=a&tags=b` |\\n| `ids` | `form`, not exploded | `ids=1,2,3` |\\n| `sort` | `pipeDelimited` | `sort=name|price` |\\n| `fields` | `spaceDelimited` | `fields=a%20b` |\\n| `filter` | `deepObject` | `filter[color]=red&filter[minSize]=2` |\\n\\nThe response shows what the server parsed.",\n        "operationId": "search",\n        "parameters": [\n          {\n            "name": "q",\n            "in": "query",\n            "description": "Free text, with two named examples.",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "minLength": 1,\n              "maxLength": 80\n            },\n            "examples": {\n              "word": {\n                "summary": "One word",\n                "value": "lamp"\n              },\n              "phrase": {\n                "summary": "A phrase",\n                "value": "desk lamp"\n              }\n            }\n          },\n          {\n            "name": "tags",\n            "in": "query",\n            "description": "Repeat the parameter: `tags=a&tags=b`.",\n            "required": false,\n            "schema": {\n              "type": "array",\n              "items": {\n                "type": "string"\n              }\n            },\n            "example": [\n              "red",\n              "sale"\n            ]\n          },\n          {\n            "name": "ids",\n            "in": "query",\n            "description": "One comma-separated value: `ids=1,2,3`.",\n            "required": false,\n            "explode": false,\n            "schema": {\n              "type": "array",\n              "items": {\n                "type": "integer",\n                "minimum": 1\n              }\n            },\n            "example": [\n              1,\n              2,\n              3\n            ]\n          },\n          {\n            "name": "sort",\n            "in": "query",\n            "description": "Sort keys joined with `|`. A leading `-` sorts descending.",\n            "required": false,\n            "style": "pipeDelimited",\n            "schema": {\n              "type": "array",\n              "items": {\n                "type": "string",\n                "enum": [\n                  "name",\n                  "price",\n                  "-name",\n                  "-price"\n                ]\n              }\n            },\n            "example": [\n              "name",\n              "-price"\n            ]\n          },\n          {\n            "name": "fields",\n            "in": "query",\n            "description": "Field names joined with a space.",\n            "required": false,\n            "style": "spaceDelimited",\n            "schema": {\n              "type": "array",\n              "items": {\n                "type": "string"\n              }\n            },\n            "example": [\n              "id",\n              "name"\n            ]\n          },\n          {\n            "name": "filter",\n            "in": "query",\n            "description": "An object spread over `filter[...]` parameters.",\n            "required": false,\n            "style": "deepObject",\n            "schema": {\n              "\$ref": "#/components/schemas/Filter"\n            }\n          },\n          {\n            "name": "status",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "enum": [\n                "draft",\n                "active",\n                "archived"\n              ],\n              "default": "active"\n            }\n          },\n          {\n            "name": "colors",\n            "in": "query",\n            "description": "Enum values repeat like any other array.",\n            "required": false,\n            "schema": {\n              "type": "array",\n              "items": {\n                "type": "string",\n                "enum": [\n                  "red",\n                  "green",\n                  "blue"\n                ]\n              }\n            }\n          },\n          {\n            "name": "page",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "integer",\n              "minimum": 1,\n              "default": 1\n            }\n          },\n          {\n            "name": "size",\n            "in": "query",\n            "required": false,\n            "schema": {\n              "type": "integer",\n              "minimum": 1,\n              "maximum": 100,\n              "default": 20\n            }\n          },\n          {\n            "name": "since",\n            "in": "query",\n            "description": "Only items changed since this moment.",\n            "required": false,\n            "schema": {\n              "type": "string",\n              "format": "date-time"\n            },\n            "example": "2026-01-01T00:00:00Z"\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/ParsedParameters"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "4XX": {\n            "description": "Any other client error.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "5XX": {\n            "description": "Any server error.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "default": {\n            "description": "Anything else.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/parameters/simple/{ids}": {\n      "get": {\n        "tags": [\n          "Parameters"\n        ],\n        "summary": "Path array, simple style",\n        "description": "Values are comma-separated: `/parameters/simple/1,2,3`.",\n        "operationId": "simplePath",\n        "parameters": [\n          {\n            "name": "ids",\n            "in": "path",\n            "required": true,\n            "schema": {\n              "type": "array",\n              "items": {\n                "type": "integer",\n                "minimum": 1\n              }\n            },\n            "example": [\n              1,\n              2,\n              3\n            ]\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json":