ion/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "default": {\n            "description": "Anything else.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/responses/jobs/{id}": {\n      "get": {\n        "tags": [\n          "Responses"\n        ],\n        "summary": "Poll a job",\n        "description": "Each poll moves the job along; the third one finds it done.",\n        "operationId": "getJob",\n        "parameters": [\n          {\n            "name": "id",\n            "in": "path",\n            "required": true,\n            "schema": {\n              "type": "integer",\n              "minimum": 1\n            }\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/JobStatus"\n                }\n              }\n            }\n          },\n          "404": {\n            "description": "No such job.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      },\n      "delete": {\n        "tags": [\n          "Responses"\n        ],\n        "summary": "Cancel a job (204 No Content)",\n        "operationId": "cancelJob",\n        "parameters": [\n          {\n            "name": "id",\n            "in": "path",\n            "required": true,\n            "schema": {\n              "type": "integer",\n              "minimum": 1\n            }\n          }\n        ],\n        "responses": {\n          "204": {\n            "description": "The job was cancelled."\n          },\n          "404": {\n            "description": "No such job.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "409": {\n            "description": "The job already finished.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/responses/status/{code}": {\n      "get": {\n        "tags": [\n          "Responses"\n        ],\n        "summary": "Get any status code",\n        "description": "Try `200`, `201`, `204`, `301`, `302`, `304`, `404`, `418`, `429`, or `503`. Redirects carry a `Location`; `429` and `503` carry `Retry-After`. A code that is not listed here still works and falls under the `2XX`, `3XX`, `4XX`, `5XX`, or `default` response, so the spec describes it.",\n        "operationId": "statusPlayground",\n        "parameters": [\n          {\n            "name": "code",\n            "in": "path",\n            "description": "The status code to return.",\n            "required": true,\n            "schema": {\n              "type": "integer",\n              "minimum": 200,\n              "maximum": 599\n            },\n            "example": 418\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK.",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Greeting"\n                }\n              }\n            }\n          },\n          "201": {\n            "description": "Created.",\n            "headers": {\n              "Location": {\n                "description": "Where to go next.",\n                "required": true,\n                "schema": {\n                  "type": "string"\n                },\n                "example": "/responses/status/200"\n              }\n            },\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Greeting"\n                }\n              }\n            }\n          },\n          "204": {\n            "description": "No content: no body at all."\n          },\n          "2XX": {\n            "description": "Any other success.",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Greeting"\n                }\n              }\n            }\n          },\n          "301": {\n            "description": "Moved permanently.",\n            "headers": {\n              "Location": {\n                "description": "Where to go next.",\n                "required": true,\n                "schema": {\n                  "type": "string"\n                },\n                "example": "/responses/status/200"\n              }\n            }\n          },\n          "302": {\n            "description": "Found.",\n            "headers": {\n              "Location": {\n                "description": "Where to go next.",\n                "required": true,\n                "schema": {\n                  "type": "string"\n                },\n                "example": "/responses/status/200"\n              }\n            }\n          },\n          "304": {\n            "description": "Not modified: no body."\n          },\n          "307": {\n            "description": "Temporary redirect that keeps the method.",\n            "headers": {\n              "Location": {\n                "description": "Where to go next.",\n                "required": true,\n                "schema": {\n                  "type": "string"\n                },\n                "example": "/responses/status/200"\n              }\n            }\n          },\n          "308": {\n            "description": "Permanent redirect that keeps the method.",\n            "headers": {\n              "Location": {\n                "description": "Where to go next.",\n                "required": true,\n                "schema": {\n                  "type": "string"\n                },\n                "example": "/responses/status/200"\n              }\n            }\n          },\n          "3XX": {\n            "description": "Any other redirect.",\n            "headers": {\n              "Location": {\n                "description": "Where to go next.",\n                "required": true,\n                "schema": {\n                  "type": "string"\n                },\n                "example": "/responses/status/200"\n              }\n            }\n          },\n          "404": {\n            "description": "Not found.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "418": {\n            "description": "I\'m a teapot.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "429": {\n            "description": "Too many requests.",\n            "headers": {\n              "Retry-After": {\n                "description": "Seconds to wait before trying again.",\n                "schema": {\n                  "type": "integer"\n                },\n                "example": 30\n              }\n            },\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "4XX": {\n            "description": "Any other client error.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "503": {\n            "description": "Unavailable.",\n            "headers": {\n              "Retry-After": {\n                "description": "Seconds to wait before trying again.",\n                "schema": {\n                  "type": "integer"\n                },\n                "example": 30\n              }\n            },\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "5XX": {\n            "description": "Any server error.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "default": {\n            "description": "Anything else.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/schemas/contact": {\n      "get": {\n        "tags": [\n          "Schemas"\n        ],\n        "summary": "anyOf: match one schema or several",\n        "description": "`?kind=email`, `?kind=phone`, or `?kind=both`. Unlike `oneOf`, a value may satisfy more than one schema, which is why `both` is valid.",\n        "operationId": "contact",\n        "parameters": [\n      