n": "DE89370400440532013000"\n                  }\n                }\n              }\n            }\n          }\n        },\n        "responses": {\n          "201": {\n            "description": "Created",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Receipt"\n                }\n              }\n            }\n          },\n          "400": {\n            "description": "The request could not be understood.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "422": {\n            "description": "The request was understood but could not be processed.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/schemas/shapes": {\n      "get": {\n        "tags": [\n          "Schemas"\n        ],\n        "summary": "A sealed class becomes oneOf",\n        "description": "`Shape` is sealed. axle finds `Circle`, `Rectangle`, and `Polygon` in the same library and emits `oneOf` with the `type` discriminator.",\n        "operationId": "shapes",\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "type": "array",\n                  "items": {\n                    "\$ref": "#/components/schemas/Shape"\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    "/schemas/tree": {\n      "get": {\n        "tags": [\n          "Schemas"\n        ],\n        "summary": "A schema that refers to itself",\n        