ers": {\n              "WWW-Authenticate": {\n                "description": "How to authenticate.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "Bearer realm=\\"showcase\\""\n              }\n            },\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          },\n          "403": {\n            "description": "The credentials are valid but not allowed here.",\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n            }\n          }\n        }\n      },\n      "post": {\n        "tags": [\n          "Security"\n        ],\n        "summary": "OAuth2: write scope",\n        "operationId": "writeItems",\n        "security": [\n          {\n            "oauth2": [\n              "items:write"\n            ]\n          }\n        ],\n        "responses": {\n          "200": {\n            "description": "OK",\n            "content": {\n              "application/json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Whoami"\n                }\n              }\n            }\n          },\n          "401": {\n            "description": "Credentials are missing or wrong.",\n            "headers": {\n              "WWW-Authenticate": {\n                "description": "How to authenticate.",\n                "schema": {\n                  "type": "string"\n                },\n                "example": "Bearer realm=\\"showcase\\""\n              }\n            },\n            "content": {\n              "application/problem+json": {\n                "schema": {\n                  "\$ref": "#/components/schemas/Problem"\n                }\n              }\n      