ge",\n          "message"\n        ],\n        "description": "A greeting, rendered in the format you ask for."\n      },\n      "HeaderEcho": {\n        "type": "object",\n        "properties": {\n          "clientTime": {\n            "type": [\n              "string",\n              "null"\n            ],\n            "format": "date-time",\n            "description": "From `X-Client-Time`."\n          },\n          "debug": {\n            "type": "boolean",\n            "description": "From `X-Debug`."\n          },\n          "featureFlags": {\n            "type": "array",\n            "items": {\n              "type": "string"\n            },\n            "description": "From `X-Feature-Flags`, split on commas."\n          },\n          "retryCount": {\n            "type": [\n              "integer",\n              "null"\n            ],\n            "description": "From `X-Retry-Count`."\n          },\n          "traceId": {\n            "type": [\n              "string",\n              "null"\n            ],\n            "description": "From `X-Trace-Id`."\n          },\n          "weights": {\n            "type": "array",\n            "items": {\n              "type": "number"\n            },\n            "description": "From `X-Weights`, split on commas."\n          }\n        },\n        "required": [\n          "debug",\n          "featureFlags",\n          "weights"\n        ],\n        "description": "The request headers, parsed into typed values."\n      },\n      "Item": {\n        "type": "object",\n        "properties": {\n          "id": {\n            "type": "integer",\n            "minimum": 1,\n            "description": "The item id."\n          },\n          "name": {\n            "type": "string",\n            "minLength": 1,\n            "maxLength": 80,\n            "description": "The item name."\n          },\n          "price": {\n            "type": "integer",\n            "minimum": 0,\n            "description": "The price in cents.